"""Fernweh & Co. storefront: a tiny Flask app with no database.

Three pages: the catalog, one product, and the about page. Product data is a
plain list in this file on purpose, so the whole storefront is readable in one
sitting.
"""
from flask import Flask, render_template_string

app = Flask(__name__)

PRODUCTS = [
    {"slug": "trailpack-32", "name": "Trailpack 32L", "price": 89.00,
     "category": "Backpacks"},
    {"slug": "summit-bottle", "name": "Summit Bottle 1L", "price": 24.00,
     "category": "Bottles"},
    {"slug": "ridge-map-pack", "name": "Ridge Map Pack", "price": 15.00,
     "category": "Maps"},
]


@app.route("/")
def catalog():
    return render_template_string(
        "<h1>Fernweh & Co.</h1><ul>{% for p in products %}"
        "<li>{{ p.name }}: ${{ p.price }}</li>{% endfor %}</ul>",
        products=PRODUCTS,
    )


@app.route("/product/<slug>")
def product(slug):
    match = next((p for p in PRODUCTS if p["slug"] == slug), None)
    if match is None:
        return "Not found", 404
    return render_template_string(
        "<h1>{{ p.name }}</h1><p>${{ p.price }}, {{ p.category }}</p>",
        p=match,
    )


@app.route("/about")
def about():
    return "Fernweh & Co. sells travel gear for people who read maps for fun."


if __name__ == "__main__":
    app.run(debug=True)
